solution.code:
import string

def password_report(pw):
    digits = symbols = upper = 0
    for ch in pw:
        if ch in string.digits:
            digits += 1
        elif ch in string.punctuation:
            symbols += 1
        elif ch in string.ascii_uppercase:
            upper += 1
    return {'digits': digits, 'symbols': symbols, 'upper': upper}

print(password_report('Ab1!'))

import os

def count_extensions(filenames):
    counts = {}
    for name in filenames:
        ext = os.path.splitext(name)[1]
        counts[ext] = counts.get(ext, 0) + 1
    return counts
